import os
import threading
import time
import six
from multiprocessing import Lock


class ProcessSafeLogger(object):
    def __init__(self, debug):
        ''' debug:
            -1   == no debug is printed
             0   == print only high priority debugs
             1   == print also msg flow
             2   == print also open/close events
             3   == print all debugs
        '''
        super(ProcessSafeLogger, self).__init__()
        self.lock = Lock()
        self.debug = debug

    def get_ts(self):
        return time.strftime("%H:%M:%S")

    def log_print(self, info, data=None, owner=None):
        self.lock.acquire()
        tname = "%s [PID:%s, Th:%s (%d/%d)]" % (self.get_ts(),
                                                os.getpid(),
                                                threading.current_thread().name,
                                                threading.current_thread().ident,
                                                threading.active_count())
        owner_name = owner
        if not isinstance(owner, six.string_types):
            owner_name = owner.__class__.__name__

        print("%-40s %-30s %s (%s)" % (tname, owner_name, info, data))
        self.lock.release()

    def debug_print(self, info, data=None, owner=None):
        if self.debug > 2:
            self.log_print(info, data, owner)

    def debug_event(self, info, data=None, owner=None):
        if self.debug > 1:
            self.log_print(info, data, owner)

    def debug_msg_flow(self, info, data=None, owner=None):
        if self.debug > 0:
            self.log_print(info, data, owner)

    def debug_high_priority(self, info, data=None, owner=None):
        if self.debug > -1:
            self.log_print(info, data, owner)
